/**
 * IPC CONTRACT — shared data types between the React frontend and the Rust backend.
 *
 * This file is the single source of truth. Rust mirrors every type in
 * `src-tauri/crates/core/src/models.rs` with `#[serde(rename_all = "camelCase")]`
 * (string unions -> enums with `#[serde(rename_all = "camelCase")]`, optional
 * fields -> `Option<T>` serialized as `null`, never omitted).
 *
 * Conventions:
 *  - Id: UUID v4 string generated by the backend.
 *  - Instants: ISO-8601 strings in UTC with `Z` (e.g. "2026-11-12T08:00:00Z").
 *  - Calendar dates: "YYYY-MM-DD". Times of day: "HH:mm".
 *  - Event start/end: ISO-8601 with offset in the event's time zone; all-day
 *    events use "YYYY-MM-DD" (end exclusive).
 *  - Do NOT change this file without updating models.rs and docs/ARCHITECTURE.md.
 */

export type Id = string;
export type IsoDateTime = string;
export type IsoDate = string;

/* ───────────────────────────── Accounts ───────────────────────────── */

export type ProviderKind = "gmail" | "outlook" | "icloud" | "yahoo" | "qq" | "netease" | "imap" | "pop3" | "local";
export type AuthKind = "oauth" | "password";
export type OAuthProvider = "google" | "microsoft";
export type Security = "tls" | "starttls" | "none";
export type AccountState = "ok" | "syncing" | "needsReauth" | "error" | "offline" | "disabled";
/** Who files a copy of outgoing mail into Sent. */
export type SentCopyMode = "server" | "client";

export interface ServerConfig {
  host: string;
  port: number;
  security: Security;
  /** Login user name; defaults to the account e-mail. */
  username: string;
}

export interface ProviderCapabilities {
  idle: boolean;
  condstore: boolean;
  qresync: boolean;
  move: boolean;
  uidplus: boolean;
  gmailExtensions: boolean;
  specialUse: boolean;
  serverSearch: boolean;
  /** Server saves sent mail itself (Gmail) -> do not APPEND to Sent. */
  autoSavesSent: boolean;
  calendar: boolean;
  contacts: boolean;
  tasks: boolean;
  taskImportance: boolean;
  taskReminders: boolean;
  taskSteps: boolean;
  taskRecurrence: boolean;
}

export interface Account {
  id: Id;
  provider: ProviderKind;
  email: string;
  displayName: string;
  /** Hex color "#RRGGBB" used in unified views. */
  color: string;
  authKind: AuthKind;
  oauthProvider: OAuthProvider | null;
  imap: ServerConfig | null;
  smtp: ServerConfig | null;
  pop3: ServerConfig | null;
  caldavUrl: string | null;
  carddavUrl: string | null;
  /** null = automatic: the provider directory decides. */
  sentCopy: SentCopyMode | null;
  /** Mail download window in days; 0 = everything. */
  syncWindowDays: number;
  mailEnabled: boolean;
  calendarEnabled: boolean;
  contactsEnabled: boolean;
  tasksEnabled: boolean;
  notificationsEnabled: boolean;
  /** Participates in the unified ("Linked") inbox. */
  includeInUnified: boolean;
  sortOrder: number;
  state: AccountState;
  stateMessage: string | null;
  capabilities: ProviderCapabilities;
  createdAt: IsoDateTime;
}

export interface DiscoveryResult {
  provider: ProviderKind;
  authKind: AuthKind;
  oauthProvider: OAuthProvider | null;
  imap: ServerConfig | null;
  smtp: ServerConfig | null;
  pop3: ServerConfig | null;
  caldavUrl: string | null;
  carddavUrl: string | null;
  /** "preset" | "ispdb" | "autoconfig" | "mx" | "guess" */
  source: string;
  /**
   * Hint for the user. Either an i18n key starting with "discovery." (e.g.
   * "discovery.note.authCode") that the frontend translates, or plain text.
   */
  note: string | null;
}

/**
 * Verified provider-directory facts for an e-mail domain.
 * `null` from the backend means the domain is not in the directory.
 */
export interface ProviderInfo {
  id: string;
  name: string;
  caldavUrl: string | null;
  carddavUrl: string | null;
  /** "configurable": the provider has a web switch that defaults to off. */
  sentCopy: SentCopyMode | "configurable";
  /** i18n key (e.g. "discovery.note.authCode") or plain text. */
  note: string | null;
  oauth: OAuthProvider | null;
}

export interface OAuthResult {
  /** Opaque handle referencing tokens held by the backend until account_create. */
  sessionId: string;
  provider: OAuthProvider;
  email: string;
  displayName: string;
}

export interface NewAccountInput {
  provider: ProviderKind;
  email: string;
  displayName: string;
  authKind: AuthKind;
  /** Password / app password / authorization code (authKind = "password"). */
  password: string | null;
  /** From auth_oauth_login (authKind = "oauth"). */
  oauthSessionId: string | null;
  imap: ServerConfig | null;
  smtp: ServerConfig | null;
  pop3: ServerConfig | null;
  caldavUrl: string | null;
  carddavUrl: string | null;
  syncWindowDays: number;
  mailEnabled: boolean;
  calendarEnabled: boolean;
  contactsEnabled: boolean;
  tasksEnabled: boolean;
}

export interface AccountPatch {
  displayName?: string;
  color?: string;
  imap?: ServerConfig | null;
  smtp?: ServerConfig | null;
  pop3?: ServerConfig | null;
  caldavUrl?: string | null;
  carddavUrl?: string | null;
  /** null = back to automatic. */
  sentCopy?: SentCopyMode | null;
  syncWindowDays?: number;
  mailEnabled?: boolean;
  calendarEnabled?: boolean;
  contactsEnabled?: boolean;
  tasksEnabled?: boolean;
  notificationsEnabled?: boolean;
  includeInUnified?: boolean;
}

/** Which DAV services have a dedicated password stored (never the secret). */
export interface DavPasswordStatus {
  calendar: boolean;
  contacts: boolean;
}

export interface ConnectionTestResult {
  imapOk: boolean | null;
  smtpOk: boolean | null;
  pop3Ok: boolean | null;
  davOk: boolean | null;
  error: string | null;
}

export interface Identity {
  id: Id;
  accountId: Id;
  name: string;
  email: string;
  replyTo: string | null;
  signatureId: Id | null;
  isDefault: boolean;
}

export interface Signature {
  id: Id;
  /** null = available for every account. */
  accountId: Id | null;
  name: string;
  html: string;
  useForNew: boolean;
  useForReply: boolean;
}

/* ─────────────────────────────── Mail ─────────────────────────────── */

export type FolderRole =
  | "inbox" | "sent" | "drafts" | "trash" | "junk" | "archive"
  | "all" | "flagged" | "important" | "outbox" | "other";

export interface Folder {
  id: Id;
  accountId: Id;
  parentId: Id | null;
  remotePath: string;
  name: string;
  role: FolderRole;
  unreadCount: number;
  totalCount: number;
  isFavorite: boolean;
  syncEnabled: boolean;
  /** \Noselect folders are shown as tree nodes only. */
  isSelectable: boolean;
  sortOrder: number;
  lastSyncAt: IsoDateTime | null;
}

export interface Address {
  name: string | null;
  email: string;
}

export type Importance = "low" | "normal" | "high";

export interface MessageSummary {
  id: Id;
  accountId: Id;
  folderId: Id;
  threadId: string;
  subject: string;
  from: Address | null;
  to: Address[];
  cc: Address[];
  date: IsoDateTime;
  preview: string;
  seen: boolean;
  flagged: boolean;
  answered: boolean;
  forwarded: boolean;
  isDraft: boolean;
  hasAttachments: boolean;
  importance: Importance;
  size: number;
  /** Messages in the conversation (1 when conversation view is off). */
  threadCount: number;
  /** Unread messages in the conversation. */
  threadUnread: number;
  /**
   * For a draft projection: `pendingConfirmation` while the remote copy is
   * unverified, `localOnly` after the user chose to keep it local.
   */
  draftSyncState?: "pendingConfirmation" | "localOnly" | null;
}

export type MailScope =
  | { kind: "folder"; folderId: Id }
  /** Unified view across accounts with includeInUnified = true. */
  | { kind: "unified"; role: FolderRole }
  | { kind: "search"; query: SearchQuery };

export type MailFilter = "all" | "unread" | "flagged" | "attachments" | "mentionsMe";

export interface MessageListQuery {
  scope: MailScope;
  filter: MailFilter;
  conversation: boolean;
  /** Opaque cursor returned by the previous page; null for first page. */
  cursor: string | null;
  limit: number;
}

export interface MessagePage {
  items: MessageSummary[];
  nextCursor: string | null;
  total: number;
  /** How a search page was produced; absent for non-search listings. */
  coverage?: SearchCoverage | null;
}

/** How much of the mailbox a search actually covered. */
export type SearchCoverage =
  | { kind: "localOnly" }
  | { kind: "server" }
  | { kind: "scanned"; scanned: number; total: number }
  | { kind: "serverUnavailable"; message: string };

/** Result of one "load older mail" batch (IMAP / Microsoft Graph folders). */
export interface LoadOlderResult {
  loaded: number;
  hasMore: boolean;
}

export interface SearchQuery {
  text: string;
  accountId: Id | null;
  folderId: Id | null;
  from: string | null;
  to: string | null;
  subject: string | null;
  hasAttachment: boolean | null;
  unread: boolean | null;
  flagged: boolean | null;
  dateFrom: IsoDate | null;
  dateTo: IsoDate | null;
  /** Also query the IMAP server (results are fetched and cached). */
  includeServer: boolean;
}

export interface Attachment {
  id: Id;
  messageId: Id;
  filename: string;
  mimeType: string;
  size: number;
  contentId: string | null;
  isInline: boolean;
  isDownloaded: boolean;
}

export interface InvitePreview {
  /** iTIP METHOD: REQUEST | CANCEL | REPLY | COUNTER | PUBLISH */
  method: string;
  event: CalendarEvent;
  /** Matching event already in a local calendar. */
  existingEventId: Id | null;
  canRespond: boolean;
  myResponse: AttendeeStatus | null;
}

export interface MessageDetail {
  summary: MessageSummary;
  to: Address[];
  cc: Address[];
  bcc: Address[];
  replyTo: Address[];
  messageIdHeader: string | null;
  inReplyTo: string | null;
  references: string[];
  /**
   * Complete sanitized HTML document ready for `<iframe sandbox srcdoc>`.
   * Includes a CSP <meta>, base styles, cid: images rewritten to the
   * backend protocol, and remote resources blocked unless allowed.
   */
  html: string;
  text: string | null;
  hasRemoteContent: boolean;
  remoteContentAllowed: boolean;
  attachments: Attachment[];
  invite: InvitePreview | null;
  listUnsubscribe: string | null;
  /** Raw RFC822 header block. */
  rawHeaders: string;
  /** Present when opened from an .eml file not stored in any account. */
  externalPath: string | null;
}

export type MessageAction =
  | { kind: "setSeen"; value: boolean }
  | { kind: "setFlagged"; value: boolean }
  | { kind: "move"; folderId: Id }
  | { kind: "archive" }
  | { kind: "delete"; permanent: boolean }
  | { kind: "markJunk"; value: boolean };

export type ReplyMode = "reply" | "replyAll" | "forward" | "forwardAsAttachment" | "editAsNew";

export interface DraftAttachment {
  id: Id;
  filename: string;
  mimeType: string;
  size: number;
  /** Local staged file path (backend-managed). */
  path: string;
  /** Inline image: referenced from HTML as cid:<contentId>. */
  contentId: string | null;
}

/**
 * Durable identity of the server copy a draft supersedes. Only `confirmed`
 * (an APPENDUID for this client's APPEND) and `explicit` (the user opened that
 * exact server draft) authorize a later delete; `candidate` must be kept.
 */
export interface RemoteDraftIdentity {
  attribution: "none" | "confirmed" | "explicit" | "candidate";
  folderId: Id | null;
  uid: number | null;
  uidvalidity: number | null;
  /** Local message row that projected the copy when the identity was pinned. */
  projectionId: Id | null;
}

export interface Draft {
  /** Local draft id (null until first save). */
  id: Id | null;
  accountId: Id;
  identityId: Id | null;
  from: Address;
  to: Address[];
  cc: Address[];
  bcc: Address[];
  subject: string;
  /** Editor HTML (inline images use cid:<contentId>). */
  html: string;
  attachments: DraftAttachment[];
  replyMode: ReplyMode | null;
  /** Local message id being replied to / forwarded. */
  sourceMessageId: Id | null;
  inReplyTo: string | null;
  references: string[];
  importance: Importance;
  requestReadReceipt: boolean;
  /** Remote message id of the draft in the Drafts folder, if synced. */
  remoteDraftMessageId: Id | null;
  /** Pinned identity of the server copy this draft supersedes. */
  remoteDraft?: RemoteDraftIdentity | null;
  /** The user chose to keep this draft local after an unconfirmed sync. */
  syncSuppressed?: boolean;
  updatedAt: IsoDateTime | null;
}

export type RuleField = "from" | "to" | "cc" | "subject" | "body" | "hasAttachment" | "anyRecipient";
export type RuleOp = "contains" | "notContains" | "equals" | "startsWith" | "endsWith" | "matchesRegex" | "isTrue";
export type RuleActionKind = "move" | "markRead" | "flag" | "delete" | "markJunk" | "archive" | "notify" | "skipNotify";

export interface RuleCondition {
  field: RuleField;
  op: RuleOp;
  value: string;
}

export interface RuleAction {
  kind: RuleActionKind;
  /** Target folder for "move". */
  folderId: Id | null;
}

export interface MailRule {
  id: Id;
  /** null = applies to all accounts. */
  accountId: Id | null;
  name: string;
  enabled: boolean;
  /** true = all conditions must match (AND); false = any (OR). */
  matchAll: boolean;
  conditions: RuleCondition[];
  actions: RuleAction[];
  stopProcessing: boolean;
  sortOrder: number;
}

export interface UnifiedCounts {
  inbox: number;
  flagged: number;
  drafts: number;
  outbox: number;
}

/* ───────────────────────────── Calendar ───────────────────────────── */

export interface Calendar {
  id: Id;
  /** Owning account; local calendars belong to the built-in "local" account. */
  accountId: Id;
  name: string;
  color: string;
  isReadOnly: boolean;
  isVisible: boolean;
  isDefault: boolean;
  /** Read-only webcal subscription. */
  subscriptionUrl: string | null;
}

export type Weekday = "MO" | "TU" | "WE" | "TH" | "FR" | "SA" | "SU";

export interface RecurrenceRule {
  freq: "daily" | "weekly" | "monthly" | "yearly";
  interval: number;
  byWeekday: Weekday[];
  /** For monthly/yearly "2nd Tuesday" style rules (with byWeekday). */
  bySetPos: number[];
  byMonthDay: number[];
  byMonth: number[];
  count: number | null;
  until: IsoDate | null;
}

export type AttendeeStatus = "needsAction" | "accepted" | "declined" | "tentative" | "delegated";
export type AttendeeRole = "required" | "optional" | "resource" | "chair";

export interface Attendee {
  email: string;
  name: string | null;
  role: AttendeeRole;
  status: AttendeeStatus;
}

export type ShowAs = "busy" | "free" | "tentative" | "oof" | "workingElsewhere";
export type EventStatus = "confirmed" | "tentative" | "cancelled";

export interface CalendarEvent {
  id: Id;
  calendarId: Id;
  accountId: Id;
  /** iCalendar UID. */
  uid: string;
  title: string;
  location: string;
  /** Plain text description. */
  description: string;
  start: string;
  end: string;
  allDay: boolean;
  /** IANA time zone, e.g. "Asia/Shanghai". */
  timeZone: string;
  recurrence: RecurrenceRule | null;
  /** Series master id when this is a detached occurrence (exception). */
  seriesId: Id | null;
  /** Original start of this occurrence for exceptions. */
  recurrenceId: string | null;
  status: EventStatus;
  showAs: ShowAs;
  isPrivate: boolean;
  organizer: Attendee | null;
  attendees: Attendee[];
  /** Minutes before start. */
  reminders: number[];
  isOrganizer: boolean;
  myResponse: AttendeeStatus | null;
  onlineMeetingUrl: string | null;
  /** Overrides calendar color when set. */
  color: string | null;
  updatedAt: IsoDateTime | null;
}

/** One concrete occurrence for rendering a time range. */
export interface EventInstance {
  eventId: Id;
  /** Stable key: `${eventId}:${start}`. */
  instanceKey: string;
  calendarId: Id;
  accountId: Id;
  title: string;
  location: string;
  start: string;
  end: string;
  allDay: boolean;
  color: string;
  isRecurring: boolean;
  showAs: ShowAs;
  status: EventStatus;
  myResponse: AttendeeStatus | null;
  hasAttendees: boolean;
  hasReminder: boolean;
}

export interface EventInput {
  calendarId: Id;
  title: string;
  location: string;
  description: string;
  start: string;
  end: string;
  allDay: boolean;
  timeZone: string;
  recurrence: RecurrenceRule | null;
  showAs: ShowAs;
  isPrivate: boolean;
  attendees: Attendee[];
  reminders: number[];
  onlineMeetingUrl: string | null;
  color: string | null;
  /** Send invitations / updates to attendees. */
  notifyAttendees: boolean;
}

export type RecurrenceEditScope = "this" | "thisAndFollowing" | "all";

