/* ───────────────────────────── Settings ───────────────────────────── */

export type ThemeMode = "system" | "light" | "dark";
export type Language = "system" | "zh-CN" | "en-US";
export type HoverAction = "archive" | "delete" | "flag" | "read" | "move" | "none";
export type CalendarView = "day" | "workWeek" | "week" | "month" | "year" | "agenda";

export interface AppSettings {
  theme: ThemeMode;
  /** null = follow system accent. */
  accentColor: string | null;
  language: Language;
  closeToTray: boolean;
  launchAtStartup: boolean;
  mail: {
    conversationView: boolean;
    remoteImages: "ask" | "trustedOnly" | "always";
    bodyCacheLimitMb: number;
    otherFoldersPollMinutes: number;
  };
  calendar: {
    defaultView: CalendarView;
    firstDayOfWeek: number;
    workDays: number[];
    workHoursStart: string;
    workHoursEnd: string;
    defaultReminderMinutes: number;
    defaultEventDurationMinutes: number;
    showWeekNumbers: boolean;
    pollMinutes: number;
  };
  contacts: {
    pollMinutes: number;
  };
  tasks: {
    pollMinutes: number;
  };
  notifications: {
    enabled: boolean;
    sound: boolean;
    showPreview: boolean;
    eventReminders: boolean;
    taskReminders: boolean;
  };
  privacy: {
    allowIspdbLookup: boolean;
  };
  updates: {
    autoCheck: boolean;
  };
  advanced: {
    googleClientId: string | null;
    /**
     * Write-only in practice: the backend stores it in the OS keyring, never in
     * the settings table. settings_get returns "********" when a secret is
     * stored (null otherwise). Sending "********" back = unchanged; "" or null = clear.
     */
    googleClientSecret: string | null;
    microsoftClientId: string | null;
  };
}

/** Deep partial used by settings_update (objects are merged, arrays replaced). */
export type SettingsPatch = {
  [K in keyof AppSettings]?: AppSettings[K] extends object
    ? AppSettings[K] extends unknown[] ? AppSettings[K] : Partial<AppSettings[K]>
    : AppSettings[K];
};

/* ─────────────────────────── Sync / app state ─────────────────────── */

export type SyncModule = "mail" | "calendar" | "contacts" | "tasks";

/** DAV services that can carry a dedicated app password. */
export type DavService = "calendar" | "contacts";
export type SyncState = "idle" | "syncing" | "retrying" | "error" | "needsReauth";

export interface SyncStatus {
  accountId: Id;
  module: SyncModule;
  state: SyncState;
  /** e.g. { done: 120, total: 800 } during initial sync. */
  progress: { done: number; total: number } | null;
  /**
   * True while a provider imports a folder's first full pass. A large Graph
   * mailbox can take several paginated rounds, so the UI says the work is
   * ongoing instead of implying the sync is stuck.
   */
  fullSync: boolean;
  /**
   * Monotonic sequence assigned when the backend commits a change. Events are
   * published after the backend releases its lock, so they can arrive out of
   * order; keep the snapshot with the highest `seq` per account+module.
   */
  seq: number;
  message: string | null;
  lastSyncAt: IsoDateTime | null;
}

export interface AppInfo {
  version: string;
  platform: "windows" | "macos" | "linux";
  dataDir: string;
  logDir: string;
  buildHasGoogleClient: boolean;
  buildHasMicrosoftClient: boolean;
}

export interface StorageUsage {
  databaseBytes: number;
  mimeCacheBytes: number;
  attachmentBytes: number;
}

export type AppModule = "mail" | "calendar" | "people" | "todo";
